/**
 * Shader de l'explosion de pixels.
 *
 * ## L'idee mathematique
 *
 * Le cadre est une trame de pixels carres, et tout ce qui s'y dessine est
 * aligne dessus : le fragment ne connait que la cellule de trame qu'il
 * occupe. Une gerbe est un point de depart, un age et une graine ; chacun de
 * ses pixels part dans une direction hachee, ralentit d'une trainee et
 * retombe sous la gravite — position analytique, rien n'est integre d'image
 * en image. Le pixel est allume si sa cellule de trame est celle du
 * fragment : pas de halo, pas de disque, un carre franc qui saute de case en
 * case.
 *
 * L'explosion elle-meme est un carre plein qui s'elargit d'une case par
 * instant et s'eteint aussitot. Un pixel qui touche le bas du cadre s'y
 * arrete un instant avant de disparaitre : c'est ce qui fait la retombee.
 *
 * Les gerbes vivent dans un tampon de cinq emplacements dates par l'horloge
 * du moteur — un depart a -1000 donne un age enorme, donc une gerbe inerte —
 * et une gerbe automatique part toute seule a un point hache.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — le fond.
 * - `uColorB`, `uColorC` — les deux teintes de pixels, melangees par gerbe.
 * - `uClicks` — cinq gerbes (x, y, temps de depart), tampon circulaire.
 * - `uPixels` — pixels de la trame sur la hauteur.
 * - `uCount` — pixels par gerbe, et donc le cout.
 * - `uGravity` — force de la retombee.
 * - `uAuto` — periode des gerbes automatiques, en secondes ; zero les coupe.
 */
export const PIXEL_BLAST_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform vec3 uClicks[5];
uniform float uPixels;
uniform float uCount;
uniform float uGravity;
uniform float uAuto;

// Nombre pseudo-aleatoire : projection sur une direction arbitraire, sinus
// amplifie, partie fractionnaire.
float blastHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Deux nombres decorreles pour une meme graine.
vec2 blastHash2(vec2 p) {
  return vec2(blastHash(p), blastHash(p + vec2(37.3, 17.7)));
}

// Lumiere qu'une gerbe depose dans la cellule de trame donnee, a l'age donne.
vec3 gerbe(vec2 cell, vec2 origine, float age, float graine, int pixels, float trame) {
  if (age < 0.0 || age > 4.0) return vec3(0.0);

  vec3 lumiere = vec3(0.0);
  float teinte = blastHash(vec2(graine, 3.1));
  float k = 1.4;
  float portee = (1.0 - exp(-k * age)) / k;
  float chute = uGravity * age * age * 0.5;
  float sol = 0.5 / trame;

  // Bornes constantes : la specification du langage l'exige ; la qualite
  // sort plus tot.
  for (int j = 0; j < 32; j += 1) {
    if (j >= pixels) break;
    float fj = float(j);
    vec2 h = blastHash2(vec2(fj, graine));

    float angle = (fj + h.x * 0.9) / float(pixels) * 6.2831853;
    float v0 = 0.25 + 0.3 * h.y;

    vec2 pos = origine + vec2(cos(angle), sin(angle)) * v0 * portee;
    pos.y -= chute;

    // Le pixel s'arrete au sol, puis s'eteint : la retombee se voit.
    float posed = step(pos.y, sol);
    pos.y = max(pos.y, sol);

    vec2 pc = floor(pos * trame);
    float hit = step(abs(pc.x - cell.x), 0.5) * step(abs(pc.y - cell.y), 0.5);

    float vie = exp(-age * (0.9 + 0.6 * h.x)) * (1.0 - posed * min(age, 1.0) * 0.6);
    vec3 couleur = mix(uColorB, uColorC, fract(teinte + h.y * 0.4));
    lumiere += couleur * hit * vie;
  }

  // L'explosion : un carre plein qui s'elargit d'une case par instant.
  vec2 oc = floor(origine * trame);
  float rayon = floor(age * 18.0);
  float carre = step(max(abs(cell.x - oc.x), abs(cell.y - oc.y)), rayon) * exp(-age * 9.0);
  lumiere += uColorC * carre;

  return lumiere;
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float trame = max(uPixels, 4.0);
  vec2 p = vec2(vUv.x * aspect, vUv.y);
  vec2 cell = floor(p * trame);
  int pixels = int(clamp(uCount, 4.0, 32.0));

  // La trame au repos : un damier a peine visible, pour que les pixels aient
  // une grille sur laquelle tomber.
  float damier = mod(cell.x + cell.y, 2.0);
  vec3 colour = mix(uColorA, uColorB, 0.025 + 0.02 * damier);

  for (int i = 0; i < 5; i += 1) {
    vec3 clic = uClicks[i];
    vec2 origine = clic.xy * vec2(aspect, 1.0);
    colour += gerbe(cell, origine, uTime - clic.z, clic.z * 7.3 + float(i), pixels, trame);
  }

  // La gerbe automatique : une par periode, a un point hache du cadre.
  if (uAuto > 0.0) {
    float periode = max(uAuto, 0.5);
    float index = floor(uTime / periode);
    float ageAuto = uTime - index * periode;
    vec2 origineAuto = vec2(0.15 + 0.7 * blastHash(vec2(index, 1.3)), 0.35 + 0.5 * blastHash(vec2(index, 9.1)));
    colour += gerbe(cell, origineAuto * vec2(aspect, 1.0), ageAuto, index * 3.7, pixels, trame);
  }

  gl_FragColor = vec4(min(colour, vec3(1.0)), 1.0);
}
`

sources.component.tsx:
/**
 * Explosion de pixels : chaque clic projette une gerbe de pixels carres qui
 * retombent.
 *
 * ## A quoi ce fond reagit
 *
 * Au clic — ou au toucher — sur le cadre : chaque appui date une gerbe dans
 * un tampon circulaire de cinq emplacements, et les pixels partent de la
 * case de trame de l'appui. Le deplacement du pointeur ne change rien.
 *
 * Une gerbe automatique part aussi toute seule, a intervalle regle : un
 * fond qui n'existe qu'au clic resterait vide dans la plupart des pages.
 * Zero la coupe.
 *
 * ## Ce qui le distingue des feux d'artifice
 *
 * Tout est aligne sur une trame : les pixels sont des carres qui sautent de
 * case en case, sans halo ni trainee, et l'explosion est un carre qui
 * s'elargit. Les feux d'artifice dessinent des etincelles rondes et floues
 * dans un espace continu.
 *
 * ## Le pont clic -> shader
 *
 * Aucun rendu React par image : le tampon est un tableau stable de quinze
 * flottants (cinq fois x, y, temps de depart), mute en place a chaque clic.
 * La surface relit ses uniforms a chaque image, l'identite du tableau ne
 * change pas — la mutation suffit.
 *
 * Le temps ecrit dans le tampon est celui de l'horloge du moteur, memorise
 * par une souscription en priorite d'entree : c'est le meme temps que
 * `uTime` du shader, sans quoi l'age des gerbes serait faux.
 *
 * ## Sous mouvement reduit
 *
 * La surface est refusee par le moteur et le repli statique s'affiche.
 *
 * @module
 */

import {
  CLOCK_PRIORITY,
  clock,
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { useEffect, useRef, useState, type ReactElement } from 'react'

import { PIXEL_BLAST_FRAGMENT } from './pixel-blast.shader.js'

/** Ce que l'echappatoire recoit. */
export interface PixelBlastControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface PixelBlastOwnProps {
  /** Pixels de la trame sur la hauteur du cadre. @defaultValue 40 */
  pixels?: number
  /** Pixels projetes par gerbe. @defaultValue 24 */
  count?: number
  /** Force de la retombee. @defaultValue 0.5 */
  gravity?: number
  /** Periode des gerbes automatiques, en secondes. Zero les coupe. @defaultValue 2.2 */
  auto?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<PixelBlastControls>
}

/** Toutes les proprietes. */
export type PixelBlastProps = Customisable<PixelBlastOwnProps>

/** Tokens employes par defaut : le fond, les deux teintes de pixels. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-brand-500',
  '--o-palette-yellow-300',
] as const

/** Repli par defaut : une teinte figee, dans les memes tons. */
const DEFAULT_FALLBACK = 'o-bg-zinc-50 dark:o-bg-zinc-950'

/** Nombre de gerbes vivantes a la fois. */
const SLOTS = 5

/**
 * Pixels par gerbe en qualite basse.
 *
 * Chaque pixel est une position et une comparaison de case par fragment,
 * pour chacune des six gerbes possibles : c'est le seul levier de cout.
 */
const LOW_COUNT = 12

/**
 * Explosion de pixels.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <PixelBlast className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function PixelBlast({
  pixels = 40,
  count = 24,
  gravity = 0.5,
  auto = 2.2,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: PixelBlastProps): ReactElement {
  const [host, setHost] = useState<HTMLDivElement | null>(null)

  // Tampon stable, mute en place : cinq fois (x, y, temps de depart). Un
  // depart a -1000 donne un age enorme, donc une gerbe inerte d'office.
  const uClicks = useRef<number[]>(Array.from({ length: SLOTS * 3 }, () => -1000)).current

  // Le temps de l'horloge du moteur — le meme que uTime du shader. C'est lui
  // qui date les gerbes ; performance.now() donnerait une autre origine.
  const lastTime = useRef(0)

  useEffect(() => {
    const subscription = clock.subscribe(
      ({ time }) => {
        lastTime.current = time
      },
      { priority: CLOCK_PRIORITY.input, name: 'pixel-blast : horloge' },
    )
    return () => subscription.unsubscribe()
  }, [])

  useEffect(() => {
    if (host === null) return

    const onDown = (event: PointerEvent): void => {
      const bounds = host.getBoundingClientRect()
      const x = (event.clientX - bounds.left) / Math.max(bounds.width, 1)
      // vUv a son origine en bas : l'axe vertical de l'ecran est inverse.
      const y = 1 - (event.clientY - bounds.top) / Math.max(bounds.height, 1)

      // Tampon circulaire : tout se decale d'un cran, la nouvelle gerbe en tete.
      for (let i = SLOTS - 1; i > 0; i -= 1) {
        uClicks[i * 3] = uClicks[(i - 1) * 3] ?? -1000
        uClicks[i * 3 + 1] = uClicks[(i - 1) * 3 + 1] ?? -1000
        uClicks[i * 3 + 2] = uClicks[(i - 1) * 3 + 2] ?? -1000
      }
      uClicks[0] = x
      uClicks[1] = y
      uClicks[2] = lastTime.current
    }

    host.addEventListener('pointerdown', onDown)
    return () => host.removeEventListener('pointerdown', onDown)
  }, [host, uClicks])

  const { ref, setHost: setShaderHost, ready, refused, colours } =
    useTokenShader<HTMLDivElement>({
      fragment: PIXEL_BLAST_FRAGMENT,
      colors,
      uniforms: {
        uClicks,
        uPixels: pixels,
        uCount: count,
        uGravity: gravity,
        uAuto: auto,
      },
      name: 'pixel-blast',
      degrade: (quality) => ({
        uCount: quality === 'low' ? Math.min(count, LOW_COUNT) : count,
      }),
    })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        setShaderHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
